/// <summary>
/// computed colume for Info 1
/// </summary>
/// <returns>
/// Info for Field 1 is filled
/// </returns>
public static server str hasInfoField1()
{
    str sInfoField1;

    sInfoField1 = SysComputedColumn::comparisonField(tableStr(AVASalesShipmentInfoFieldView), tableStr(KCS_SOCSalesTableInfoFields), fieldStr(KCS_SOCSalesTableInfoFields, InfoField1));

    return SysComputedColumn::if(SysComputedColumn::isNullExpression(sInfoField1),
                                    SysComputedColumn::returnLiteral(NoYes::No),
                                    SysComputedColumn::returnLiteral(NoYes::Yes));

}

