/// <summary>
/// computed colume for Info 3or4
/// </summary>
/// <returns>
/// Info for Field 3 or 4 is filled
/// </returns>
public static server str hasInfoField3Or4()
{
    str         sInfoField3;
    str         sInfoField4;

    sInfoField3 = SysComputedColumn::comparisonField(tableStr(AVASalesShipmentInfoFieldView), tableStr(KCS_SOCSalesTableInfoFields), fieldStr(KCS_SOCSalesTableInfoFields, InfoField3));
    sInfoField4 = SysComputedColumn::comparisonField(tableStr(AVASalesShipmentInfoFieldView), tableStr(KCS_SOCSalesTableInfoFields), fieldStr(KCS_SOCSalesTableInfoFields, InfoField4));        

    return SysComputedColumn::if(SysComputedColumn::isNullExpression(sInfoField3),
                                    SysComputedColumn::if(SysComputedColumn::isNullExpression(sInfoField4),
                                        SysComputedColumn::returnLiteral(NoYes::No),
                                        SysComputedColumn::returnLiteral(NoYes::Yes)),
                                    SysComputedColumn::returnLiteral(NoYes::Yes));
}

/// <summary> /// N.Freidenberher 20.02.2025 /// </summary> public static str getDropOffDate() { DictView shipmentTableCalcDateView = new DictView(tableNum(AVASalesShipmentInfoFieldView)); str shipmentTableDSName = shipmentTableCalcDateView.query().dataSourceTable(tableNum(WHSShipmentTable)).name();
str dropOffDate = strFmt(@"SELECT case when (%1 = 1) then CONVERT(DATE,table_a.ShipmentArrivalUTCDateTime) when (%1 = 2 and %3 = 2 and RC_req > 0 and MinRecDateRequested <> '1900-01-01 00:00:00.000') then MinRecDateRequested when (%1 = 2 and %3 = 2 and RC_conf > 0) then MinRecDateConfirm when (%1 = 2 and %3 = 5) then ReceiveDate end as dropDate from (SELECT ShipmentArrivalUTCDateTime, ShipmentId FROM WHSSHIPMENTTABLE WHERE SHIPMENTID = %2 and DataAreaId = %4) AS table_a, (SELECT MIN(ReceiptDateConfirmed) as MinRecDateConfirm, COUNT(SalesLine.RECID) AS RC_conf FROM salesLine join WHSLOADLINE as load1 on salesLine.INVENTTRANSID = load1.INVENTTRANSID where load1.SHIPMENTID = %2 and load1.INVENTTRANSTYPE = 0 and salesLine.RECEIPTDATECONFIRMED <> '1900-01-01 00:00:00.000' and salesLine.dataAreaId = %4) AS confirmLine, (SELECT MIN(RECEIPTDATEREQUESTED) as MinRecDateRequested, COUNT(SalesLine.RECID) AS RC_req
FROM salesLine join WHSLOADLINE as load2 on salesLine.INVENTTRANSID = load2.INVENTTRANSID where load2.SHIPMENTID = %2 and load2.INVENTTRANSTYPE = 0 and salesLine.RECEIPTDATECONFIRMED = '1900-01-01 00:00:00.000' and salesLine.DataAreaId = %4) AS requestedLine, (SELECT MIN(ReceiveDate) as ReceiveDate FROM inventTransferLine join WHSLOADLINE on inventTransferLine.INVENTTRANSID = whsLoadLine.INVENTTRANSID where inventTransferLine.ReceiveDate <> '1900-01-01 00:00:00.000' and WHSLOADLINE.ShipmentId = %2 and WHSLOADLINE.InventTransType = 21 and inventTransferLine.DataAreaId = %4) as table_d", SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,LoadDirection)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,ShipmentId)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,WorkTransType)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,DataAreaId)));
return dropOffDate; }

public static str getPickUpDate() { DictView shipmentTableCalcDateView = new DictView(tableNum(AVASalesShipmentInfoFieldView)); str shipmentTableDSName = shipmentTableCalcDateView.query().dataSourceTable(tableNum(WHSShipmentTable)).name();
str shipDate = strFmt(@"SELECT case when (%1 = 1) then CONVERT(DATE,table_a.ShipmentArrivalUTCDateTime) when (%1 = 2 and %3 = 2 and RC_req > 0 and MinShipDateRequested <> '1900-01-01 00:00:00.000') then MinShipDateRequested when (%1 = 2 and %3 = 2 and RC_conf > 0) then MinShipDateConfirm when (%1 = 2 and %3 = 5) then ReceiveDate end as dropDate from (SELECT ShipmentArrivalUTCDateTime, ShipmentId FROM WHSSHIPMENTTABLE WHERE SHIPMENTID = %2 and DataAreaId = %4) AS table_a, (SELECT MIN(ShippingDateConfirmed) as MinShipDateConfirm, COUNT(SalesLine.RECID) AS RC_conf FROM salesLine join WHSLOADLINE as load1 on salesLine.INVENTTRANSID = load1.INVENTTRANSID where load1.SHIPMENTID = %2 and load1.INVENTTRANSTYPE = 0 and salesLine.ShippingDateConfirmed <> '1900-01-01 00:00:00.000' and salesLine.dataAreaId = %4) AS confirmLine, (SELECT MIN(ShippingDateRequested) as MinShipDateRequested, COUNT(SalesLine.RECID) AS RC_req
FROM salesLine join WHSLOADLINE as load2 on salesLine.INVENTTRANSID = load2.INVENTTRANSID where load2.SHIPMENTID = %2 and load2.INVENTTRANSTYPE = 0 and salesLine.ShippingDateConfirmed = '1900-01-01 00:00:00.000' and salesLine.DataAreaId = %4) AS requestedLine, (SELECT MIN(ShipDate) as ReceiveDate FROM inventTransferLine join WHSLOADLINE on inventTransferLine.INVENTTRANSID = whsLoadLine.INVENTTRANSID where inventTransferLine.ShipDate <> '1900-01-01 00:00:00.000' and WHSLOADLINE.ShipmentId = %2 and WHSLOADLINE.InventTransType = 21 and inventTransferLine.DataAreaId = %4) as table_d", SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,LoadDirection)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,ShipmentId)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,WorkTransType)), SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,DataAreaId)));
return shipDate; }

/// <summary>
/// N.Freidenberger
/// </summary>
public static str hasCrossDocu()
{
    DictView    shipmentTableCalcDateView = new DictView(tableNum(AVASalesShipmentInfoFieldView));
    str         shipmentTableDSName = shipmentTableCalcDateView.query().dataSourceTable(tableNum(WHSShipmentTable)).name();

    str crossCompanyQty = strFmt(@"select case when  sum(WL1.CrossDockQuantity) > 0
                                    then 1
                                    else 0
                                   end as CR
                                 from WHSLOADLINE as WL1 where WL1.SHIPMENTID = %1 ",
    SysComputedColumn::returnField(tableStr(AVASalesShipmentInfoFieldView),shipmentTableDSName,fieldStr(AVASalesShipmentInfoFieldView,ShipmentId)));
    return    crossCompanyQty;
}
